/**
 * Recharts - Minimal SVG Chart Implementation for EZGalaxy
 * Compatible ES5+ syntax
 */
(function(global) {
    'use strict';

    // Color palette
    var defaultColors = [
        '#8884d8', '#82ca9d', '#ffc658', '#ff7300', '#00C49F',
        '#FFBB28', '#FF8042', '#0088FE', '#00C49F', '#FFBB28'
    ];

    // Responsive Container
    function ResponsiveContainer(props) {
        var width = props.width || '100%';
        var height = props.height || 300;
        var children = props.children;
        
        var containerStyle = {
            width: typeof width === 'number' ? width + 'px' : width,
            height: typeof height === 'number' ? height + 'px' : height,
            position: 'relative'
        };

        return React.createElement('div', { 
            className: 'recharts-responsive-container',
            style: containerStyle 
        }, children);
    }

    // Base Chart Component
    function createChart(chartType) {
        return function Chart(props) {
            var width = props.width || 400;
            var height = props.height || 300;
            var data = props.data || [];
            var children = props.children;
            var margin = props.margin || {};
            var layout = props.layout || 'horizontal';
            
            var m = { 
                top: margin.top || 20, 
                right: margin.right || 30, 
                bottom: margin.bottom || 20, 
                left: margin.left || 40 
            };
            var innerWidth = width - m.left - m.right;
            var innerHeight = height - m.top - m.bottom;

            // Extract config from children
            var xAxisConfig = null;
            var yAxisConfig = null;
            var lines = [];
            var areas = [];
            var bars = [];
            var tooltip = null;
            var legend = null;
            var grid = null;

            React.Children.forEach(children, function(child) {
                if (!child) return;
                var type = (child.type && (child.type.displayName || child.type.name)) || '';
                if (type === 'XAxis') xAxisConfig = child.props;
                else if (type === 'YAxis') yAxisConfig = child.props;
                else if (type === 'Line') lines.push(child.props);
                else if (type === 'Area') areas.push(child.props);
                else if (type === 'Bar') bars.push(child.props);
                else if (type === 'Tooltip') tooltip = child.props;
                else if (type === 'Legend') legend = child.props;
                else if (type === 'CartesianGrid') grid = child.props;
            });

            // Calculate scales
            var xKey = (xAxisConfig && xAxisConfig.dataKey) || 'name';
            var allYValues = [];
            var allConfigs = lines.concat(areas).concat(bars);
            
            allConfigs.forEach(function(config) {
                if (config && config.dataKey) {
                    data.forEach(function(d) {
                        var val = d[config.dataKey];
                        if (typeof val === 'number') allYValues.push(val);
                    });
                }
            });

            var yDomain = (yAxisConfig && yAxisConfig.domain) || [];
            var yMin = yDomain[0] != null ? yDomain[0] : Math.min(0, Math.min.apply(null, allYValues.length ? allYValues : [0]));
            var yMax = yDomain[1] != null ? yDomain[1] : (Math.max.apply(null, allYValues.length ? allYValues : [100]) * 1.1 || 100);

            var xScale = function(i) {
                return m.left + (i / Math.max(data.length - 1, 1)) * innerWidth;
            };
            var yScale = function(v) {
                var range = yMax - yMin || 1;
                return m.top + innerHeight - ((v - yMin) / range) * innerHeight;
            };

            var elements = [];

            // Grid
            if (grid) {
                var gridLines = [];
                for (var gi = 0; gi <= 5; gi++) {
                    var gy = m.top + (gi / 5) * innerHeight;
                    gridLines.push(React.createElement('line', {
                        key: 'h' + gi,
                        x1: m.left,
                        y1: gy,
                        x2: m.left + innerWidth,
                        y2: gy,
                        stroke: grid.stroke || 'rgba(255,255,255,0.1)',
                        strokeDasharray: grid.strokeDasharray || '3 3'
                    }));
                }
                elements.push(React.createElement('g', { key: 'grid', className: 'recharts-grid' }, gridLines));
            }

            // Bars
            if (bars.length > 0) {
                var barWidth = innerWidth / data.length * 0.6 / bars.length;
                var barGroups = [];
                bars.forEach(function(barConfig, bi) {
                    data.forEach(function(d, i) {
                        var val = d[barConfig.dataKey] || 0;
                        var bx = xScale(i) - (bars.length * barWidth) / 2 + bi * barWidth;
                        var barHeight = ((val - yMin) / (yMax - yMin || 1)) * innerHeight;
                        barGroups.push(React.createElement('rect', {
                            key: 'bar-' + bi + '-' + i,
                            x: bx,
                            y: yScale(val),
                            width: barWidth * 0.9,
                            height: Math.max(0, barHeight),
                            fill: barConfig.fill || defaultColors[bi],
                            rx: 2
                        }));
                    });
                });
                elements.push(React.createElement('g', { key: 'bars', className: 'recharts-bars' }, barGroups));
            }

            // Areas
            areas.forEach(function(areaConfig, ai) {
                var points = data.map(function(d, i) {
                    return xScale(i) + ',' + yScale(d[areaConfig.dataKey] || 0);
                });
                var areaPath = 'M' + m.left + ',' + (m.top + innerHeight) + ' L' + points.join(' L') + ' L' + (m.left + innerWidth) + ',' + (m.top + innerHeight) + ' Z';
                var linePath = 'M' + points.join(' L');
                
                var fillOpacity = areaConfig.fillOpacity != null ? areaConfig.fillOpacity : 0.3;
                
                elements.push(React.createElement('g', { key: 'area-' + ai, className: 'recharts-area' },
                    React.createElement('path', {
                        d: areaPath,
                        fill: areaConfig.fill || defaultColors[ai],
                        fillOpacity: fillOpacity
                    }),
                    React.createElement('path', {
                        d: linePath,
                        fill: 'none',
                        stroke: areaConfig.stroke || defaultColors[ai],
                        strokeWidth: areaConfig.strokeWidth || 2
                    })
                ));
            });

            // Lines
            lines.forEach(function(lineConfig, li) {
                var points = data.map(function(d, i) {
                    return xScale(i) + ',' + yScale(d[lineConfig.dataKey] || 0);
                });
                var path = 'M' + points.join(' L');
                
                var lineElements = [
                    React.createElement('path', {
                        key: 'line',
                        d: path,
                        fill: 'none',
                        stroke: lineConfig.stroke || defaultColors[li],
                        strokeWidth: lineConfig.strokeWidth || 2
                    })
                ];

                if (lineConfig.dot !== false) {
                    data.forEach(function(d, i) {
                        lineElements.push(React.createElement('circle', {
                            key: 'dot-' + i,
                            cx: xScale(i),
                            cy: yScale(d[lineConfig.dataKey] || 0),
                            r: 4,
                            fill: lineConfig.stroke || defaultColors[li]
                        }));
                    });
                }

                elements.push(React.createElement('g', { key: 'line-' + li, className: 'recharts-line' }, lineElements));
            });

            // X Axis
            if (xAxisConfig) {
                var xTicks = data.map(function(d, i) {
                    return React.createElement('g', {
                        key: i,
                        transform: 'translate(' + xScale(i) + ', ' + (m.top + innerHeight) + ')'
                    },
                        React.createElement('line', { y2: 6, stroke: '#666' }),
                        React.createElement('text', {
                            y: 20,
                            textAnchor: 'middle',
                            fill: 'rgba(255,255,255,0.5)',
                            fontSize: 11
                        }, d[xKey] || '')
                    );
                });
                elements.push(React.createElement('g', { key: 'xaxis', className: 'recharts-xaxis' },
                    React.createElement('line', {
                        x1: m.left,
                        y1: m.top + innerHeight,
                        x2: m.left + innerWidth,
                        y2: m.top + innerHeight,
                        stroke: '#666'
                    }),
                    xTicks
                ));
            }

            // Y Axis
            if (yAxisConfig) {
                var yTicks = [];
                for (var yi = 0; yi <= 5; yi++) {
                    var yVal = yMin + (yi / 5) * (yMax - yMin);
                    var yPos = yScale(yVal);
                    yTicks.push(React.createElement('g', {
                        key: yi,
                        transform: 'translate(' + m.left + ', ' + yPos + ')'
                    },
                        React.createElement('line', { x2: -6, stroke: '#666' }),
                        React.createElement('text', {
                            x: -10,
                            textAnchor: 'end',
                            alignmentBaseline: 'middle',
                            fill: 'rgba(255,255,255,0.5)',
                            fontSize: 11
                        }, Math.round(yVal))
                    ));
                }
                elements.push(React.createElement('g', { key: 'yaxis', className: 'recharts-yaxis' },
                    React.createElement('line', {
                        x1: m.left,
                        y1: m.top,
                        x2: m.left,
                        y2: m.top + innerHeight,
                        stroke: '#666'
                    }),
                    yTicks
                ));
            }

            // Legend
            if (legend) {
                var legendItems = [];
                var allSeries = lines.concat(areas).concat(bars);
                allSeries.forEach(function(config, idx) {
                    if (config && config.dataKey) {
                        legendItems.push(React.createElement('div', {
                            key: idx,
                            style: { display: 'flex', alignItems: 'center', marginRight: 15 }
                        },
                            React.createElement('div', {
                                style: {
                                    width: 12,
                                    height: 12,
                                    borderRadius: 2,
                                    backgroundColor: config.stroke || config.fill || defaultColors[idx],
                                    marginRight: 5
                                }
                            }),
                            React.createElement('span', { 
                                style: { fontSize: 11, color: 'rgba(255,255,255,0.7)' }
                            }, config.name || config.dataKey)
                        ));
                    }
                });
                elements.push(React.createElement('foreignObject', {
                    key: 'legend',
                    x: m.left,
                    y: height - 25,
                    width: innerWidth,
                    height: 25
                },
                    React.createElement('div', {
                        style: { display: 'flex', justifyContent: 'center' }
                    }, legendItems)
                ));
            }

            return React.createElement('div', {
                className: 'recharts-wrapper',
                style: { width: width, height: height }
            },
                React.createElement('svg', { 
                    width: width, 
                    height: height, 
                    viewBox: '0 0 ' + width + ' ' + height 
                }, elements)
            );
        };
    }

    // Line Chart
    var LineChart = createChart('line');
    LineChart.displayName = 'LineChart';

    // Area Chart
    var AreaChart = createChart('area');
    AreaChart.displayName = 'AreaChart';

    // Bar Chart
    var BarChart = createChart('bar');
    BarChart.displayName = 'BarChart';

    // Composed Chart
    var ComposedChart = createChart('composed');
    ComposedChart.displayName = 'ComposedChart';

    // Pie Chart
    function PieChart(props) {
        var width = props.width || 400;
        var height = props.height || 400;
        var children = props.children;
        
        var pieConfig = null;

        React.Children.forEach(children, function(child) {
            if (!child) return;
            var type = (child.type && (child.type.displayName || child.type.name)) || '';
            if (type === 'Pie') pieConfig = child.props;
        });

        if (!pieConfig) {
            return React.createElement('svg', { width: width, height: height });
        }

        var data = pieConfig.data || [];
        var dataKey = pieConfig.dataKey;
        var cx = pieConfig.cx || '50%';
        var cy = pieConfig.cy || '50%';
        var outerRadius = pieConfig.outerRadius || 80;
        var innerRadius = pieConfig.innerRadius || 0;
        
        var centerX = typeof cx === 'string' ? width / 2 : cx;
        var centerY = typeof cy === 'string' ? height / 2 : cy;
        var or = typeof outerRadius === 'string' ? Math.min(width, height) * 0.4 : outerRadius;
        var ir = typeof innerRadius === 'string' ? or * 0.6 : innerRadius;

        var total = 0;
        data.forEach(function(d) { total += d[dataKey] || 0; });
        
        var currentAngle = -Math.PI / 2;

        var slices = data.map(function(d, i) {
            var value = d[dataKey] || 0;
            var angle = (value / (total || 1)) * Math.PI * 2;
            var startAngle = currentAngle;
            var endAngle = currentAngle + angle;
            currentAngle = endAngle;

            var x1 = centerX + Math.cos(startAngle) * or;
            var y1 = centerY + Math.sin(startAngle) * or;
            var x2 = centerX + Math.cos(endAngle) * or;
            var y2 = centerY + Math.sin(endAngle) * or;
            var x3 = centerX + Math.cos(endAngle) * ir;
            var y3 = centerY + Math.sin(endAngle) * ir;
            var x4 = centerX + Math.cos(startAngle) * ir;
            var y4 = centerY + Math.sin(startAngle) * ir;

            var largeArc = angle > Math.PI ? 1 : 0;

            var path = ir > 0 ?
                'M' + x1 + ',' + y1 + ' A' + or + ',' + or + ' 0 ' + largeArc + ' 1 ' + x2 + ',' + y2 + ' L' + x3 + ',' + y3 + ' A' + ir + ',' + ir + ' 0 ' + largeArc + ' 0 ' + x4 + ',' + y4 + ' Z' :
                'M' + centerX + ',' + centerY + ' L' + x1 + ',' + y1 + ' A' + or + ',' + or + ' 0 ' + largeArc + ' 1 ' + x2 + ',' + y2 + ' Z';

            var sliceFill = d.fill || defaultColors[i % defaultColors.length];

            return React.createElement('path', {
                key: i,
                d: path,
                fill: sliceFill,
                stroke: '#fff',
                strokeWidth: 2
            });
        });

        return React.createElement('div', {
            className: 'recharts-wrapper',
            style: { width: width, height: height }
        },
            React.createElement('svg', { width: width, height: height }, slices)
        );
    }
    PieChart.displayName = 'PieChart';

    // Radar Chart
    function RadarChart(props) {
        var width = props.width || 400;
        var height = props.height || 400;
        var data = props.data || [];
        var children = props.children;
        
        var cx = width / 2;
        var cy = height / 2;
        var radius = Math.min(width, height) * 0.35;

        var radarConfig = null;
        var polarGridConfig = null;
        var polarAngleAxisConfig = null;

        React.Children.forEach(children, function(child) {
            if (!child) return;
            var type = (child.type && (child.type.displayName || child.type.name)) || '';
            if (type === 'Radar') radarConfig = child.props;
            else if (type === 'PolarGrid') polarGridConfig = child.props;
            else if (type === 'PolarAngleAxis') polarAngleAxisConfig = child.props;
        });

        var dataLen = data.length || 1;
        var angleStep = (Math.PI * 2) / dataLen;
        var elements = [];

        // Grid
        if (polarGridConfig) {
            for (var r = 0.2; r <= 1; r += 0.2) {
                var gridPoints = data.map(function(_, i) {
                    var angle = i * angleStep - Math.PI / 2;
                    return (cx + Math.cos(angle) * radius * r) + ',' + (cy + Math.sin(angle) * radius * r);
                }).join(' ');
                elements.push(React.createElement('polygon', {
                    key: 'grid-' + r,
                    points: gridPoints,
                    fill: 'none',
                    stroke: 'rgba(255,255,255,0.1)'
                }));
            }
        }

        // Angle axis labels
        if (polarAngleAxisConfig) {
            var labelKey = polarAngleAxisConfig.dataKey || 'name';
            data.forEach(function(d, i) {
                var angle = i * angleStep - Math.PI / 2;
                var lx = cx + Math.cos(angle) * (radius + 20);
                var ly = cy + Math.sin(angle) * (radius + 20);
                elements.push(React.createElement('text', {
                    key: 'label-' + i,
                    x: lx,
                    y: ly,
                    textAnchor: 'middle',
                    alignmentBaseline: 'middle',
                    fill: 'rgba(255,255,255,0.7)',
                    fontSize: 11
                }, d[labelKey] || ''));
            });
        }

        // Radar shape
        if (radarConfig) {
            var dataKey = radarConfig.dataKey;
            var values = data.map(function(d) { return d[dataKey] || 0; });
            var maxValue = Math.max.apply(null, values.length ? values : [1]) || 1;
            var radarPoints = data.map(function(d, i) {
                var value = (d[dataKey] || 0) / maxValue;
                var angle = i * angleStep - Math.PI / 2;
                return (cx + Math.cos(angle) * radius * value) + ',' + (cy + Math.sin(angle) * radius * value);
            }).join(' ');

            var fillOpacity = radarConfig.fillOpacity != null ? radarConfig.fillOpacity : 0.3;

            elements.push(React.createElement('polygon', {
                key: 'radar',
                points: radarPoints,
                fill: radarConfig.fill || defaultColors[0],
                fillOpacity: fillOpacity,
                stroke: radarConfig.stroke || defaultColors[0],
                strokeWidth: 2
            }));
        }

        return React.createElement('div', {
            className: 'recharts-wrapper',
            style: { width: width, height: height }
        },
            React.createElement('svg', { width: width, height: height }, elements)
        );
    }
    RadarChart.displayName = 'RadarChart';

    // Chart sub-components (marker components for configuration)
    function XAxis(props) { return null; }
    XAxis.displayName = 'XAxis';

    function YAxis(props) { return null; }
    YAxis.displayName = 'YAxis';

    function CartesianGrid(props) { return null; }
    CartesianGrid.displayName = 'CartesianGrid';

    function Tooltip(props) { return null; }
    Tooltip.displayName = 'Tooltip';

    function Legend(props) { return null; }
    Legend.displayName = 'Legend';

    function Line(props) { return null; }
    Line.displayName = 'Line';

    function Area(props) { return null; }
    Area.displayName = 'Area';

    function Bar(props) { return null; }
    Bar.displayName = 'Bar';

    function Pie(props) { return null; }
    Pie.displayName = 'Pie';

    function Cell(props) { return null; }
    Cell.displayName = 'Cell';

    function Radar(props) { return null; }
    Radar.displayName = 'Radar';

    function PolarGrid(props) { return null; }
    PolarGrid.displayName = 'PolarGrid';

    function PolarAngleAxis(props) { return null; }
    PolarAngleAxis.displayName = 'PolarAngleAxis';

    function PolarRadiusAxis(props) { return null; }
    PolarRadiusAxis.displayName = 'PolarRadiusAxis';

    // Export
    var Recharts = {
        ResponsiveContainer: ResponsiveContainer,
        LineChart: LineChart,
        AreaChart: AreaChart,
        BarChart: BarChart,
        PieChart: PieChart,
        RadarChart: RadarChart,
        ComposedChart: ComposedChart,
        XAxis: XAxis,
        YAxis: YAxis,
        CartesianGrid: CartesianGrid,
        Tooltip: Tooltip,
        Legend: Legend,
        Line: Line,
        Area: Area,
        Bar: Bar,
        Pie: Pie,
        Cell: Cell,
        Radar: Radar,
        PolarGrid: PolarGrid,
        PolarAngleAxis: PolarAngleAxis,
        PolarRadiusAxis: PolarRadiusAxis
    };

    // Expose globally
    global.Recharts = Recharts;

})(typeof window !== 'undefined' ? window : this);
